rint", "cited_by_count": 0, "open_access": {"is_oa": true, "oa_status": "green", "oa_url": "https://arxiv.org/pdf/2605.20025", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2605.20025", "doi": null, "is_oa": true, "landing_page_url": "https://arxiv.org/abs/2605.20025", "pdf_url": "https://arxiv.org/pdf/2605.20025", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": null, "license_id": null, "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "Automating scientific discovery requires more than generating papers from ideas. Real research is iterative: hypotheses are challenged from multiple perspectives, experiments fail and inform the next attempt, and lessons accumulate across cycles. Existing autonomous research systems often model this process as a linear pipeline: they rely on single-agent reasoning, stop when execution fails, and do not carry experience across runs. We present AutoResearchClaw, a multi-agent autonomous research pipeline built on five mechanisms: structured multi-agent debate for hypothesis generation and result analysis, a self-healing executor with a \\textsc{Pivot}/\\textsc{Refine} decision loop that transforms failures into information, verifiable result reporting that prevents fabricated numbers and hallucinated citations, human-in-the-loop collaboration with seven intervention modes spanning full autonomy to step-by-step oversight, and cross-run evolution that converts past mistakes into future safeguards. On ARC-Bench, a 25-topic experiment-stage benchmark, AutoResearchClaw outperforms AI Scientist v2 by 54.7%. A human-in-the-loop ablation across seven intervention modes reveals that precise, targeted collaboration at high-leverage decision points consistently outperforms both full autonomy and exhaustive step-by-step oversight. We position AutoResearchClaw as a research amplifier that augments rather than replaces human scientific judgment. Code is available at https://github.com/aiming-lab/AutoResearchClaw."}]", "excerpt_truncated": true, "source_sha256": "26383d8e1d7124cfbbfca487c68a547a3ee77135f18fa16875716dc5911b0929", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1039/d4sc03921a", "openalex:W4405185373", "arxiv:2605.20025"], "source_candidates": ["https://doi.org/10.1039/d4sc03921a", "https://arxiv.org/pdf/2605.20025", "https://arxiv.org/abs/2605.20025"], "source_candidate_identities": {}}

